import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.ArrayList;import java.util.StringTokenizer;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String line = br.readLine();if (line == null) return;int n = Integer.parseInt(line.trim());if (n <= 0) {System.out.println(0);return;}ArrayList<Integer>[] adj = new ArrayList[n + 1];for (int i = 1; i <= n; i++) adj[i] = new ArrayList<Integer>();for (int i = 0; i < n - 1; i++) {String lineEdge = br.readLine();if (lineEdge == null) break;StringTokenizer st = new StringTokenizer(lineEdge);int u = Integer.parseInt(st.nextToken());int v = Integer.parseInt(st.nextToken());adj[u].add(v);adj[v].add(u);}boolean[] visited = new boolean[n + 1];int[] stack = new int[n + 1];int[] dStack = new int[n + 1];int top = 0;stack[top] = 1;dStack[top] = 0;visited[1] = true;long totalPairs = 0;while (top >= 0) {int u = stack[top];int d = dStack[top--];totalPairs += (d + 1);for (int i = 0; i < adj[u].size(); i++) {int v = adj[u].get(i);if (!visited[v]) {visited[v] = true;top++;stack[top] = v;dStack[top] = d + 1;}}}System.out.println(totalPairs);}}